function validate([nums, x, k]) {
  const n = nums.length;
  if (n < 2 || n > 100000) return 'nums needs 2 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -1000000 || v > 1000000)) return 'Each value of nums is an integer from -10^6 to 10^6.';
  if (!Number.isInteger(x) || x < 2 || x > n) return 'x is between 2 and nums.length.';
  if (!Number.isInteger(k) || k < 1 || k > 15) return 'k is between 1 and 15.';
  if (k * x > n) return 'k * x must not exceed nums.length.';
  return null;
}

