function minOperations(nums, x, k) {
  const n = nums.length;
  const values = [...new Set(nums)].sort((a, b) => a - b);
  const rank = new Map(values.map((value, i) => [value, i + 1]));
  const size = values.length;
  const counts = new Array(size + 1).fill(0);
  const sums = new Array(size + 1).fill(0);
  const update = (value, sign) => {
    for (let i = rank.get(value); i <= size; i += i & -i) {
      counts[i] += sign;
      sums[i] += sign * value;
    }
  };
  let top = 1;
  while (top * 2 <= size) top *= 2;
  const half = Math.ceil(x / 2);
  const cost = new Array(n - x + 1).fill(0);
  let windowSum = 0;
  for (let right = 0; right < n; right++) {
    update(nums[right], 1);
    windowSum += nums[right];
    if (right >= x) {
      update(nums[right - x], -1);
      windowSum -= nums[right - x];
    }
    if (right < x - 1) continue;
    let position = 0;
    let below = 0;
    let belowSum = 0;
    for (let step = top; step > 0; step >>= 1) {
      const jump = position + step;
      if (jump <= size && below + counts[jump] < half) {
        position = jump;
        below += counts[jump];
        belowSum += sums[jump];
      }
    }
    const median = values[position];
    cost[right - x + 1] = (median * below - belowSum) + (windowSum - belowSum - median * (x - below));
  }
  let prev = new Array(n + 1).fill(0);
  for (let j = 1; j <= k; j++) {
    const curr = new Array(n + 1).fill(Infinity);
    for (let i = j * x; i <= n; i++) {
      curr[i] = Math.min(curr[i - 1], prev[i - x] + cost[i - x]);
    }
    prev = curr;
  }
  return prev[n];
}

