function minOperations(nums, x, k) {
  const n = nums.length;
  // Cost to make nums[s..s+x-1] equal: try every value of the window as the common value.
  const windowCost = (s) => {
    let least = Infinity;
    for (let t = s; t < s + x; t++) {
      let total = 0;
      for (let i = s; i < s + x; i++) total += Math.abs(nums[i] - nums[t]);
      least = Math.min(least, total);
    }
    return least;
  };
  // fewest(start, left): cheapest way to place left windows inside nums[start..].
  const memo = new Map();
  const fewest = (start, left) => {
    if (left === 0) return 0;
    if (n - start < left * x) return Infinity;
    const key = start * 16 + left;
    if (memo.has(key)) return memo.get(key);
    // Either no window starts at start, or one does and the next may start right after it.
    const result = Math.min(fewest(start + 1, left), windowCost(start) + fewest(start + x, left - 1));
    memo.set(key, result);
    return result;
  };
  return fewest(0, k);
}

