function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(1500, 2000) : int(2, 10);
  const k = size === 'large' ? int(1, 15) : int(1, Math.min(15, Math.floor(n / 2)));
  const x = int(2, Math.floor(n / k));
  const kind = rand();
  const span = kind < 0.3 ? 3 : kind < 0.6 ? 20 : 1000000;
  const nums = Array.from({ length: n }, () => (rand() < 0.08 ? (rand() < 0.5 ? -1000000 : 1000000) : int(-span, span)));
  if (rand() < 0.2) {
    // Plant a stretch of equal values so that zero-cost windows appear.
    const at = int(0, n - x), value = nums[at];
    for (let i = at; i < at + x; i++) nums[i] = value;
  }
  return [nums, x, k];
}
